package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="conversation_participants",uniqueConstraints=@UniqueConstraint(columnNames={"conversation_id","user_id"})) public class ConversationParticipant {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="conversation_id",nullable=false) private Long conversationId; @Column(name="user_id",nullable=false) private Long userId; @Column(name="joined_at",nullable=false) private LocalDateTime joinedAt; @Column(name="last_read_at") private LocalDateTime lastReadAt; @Column(nullable=false) private boolean muted; @Column(nullable=false) private boolean archived; @Column(nullable=false) private boolean deleted;
 public Long getId(){return id;} public Long getConversationId(){return conversationId;} public void setConversationId(Long v){conversationId=v;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public LocalDateTime getJoinedAt(){return joinedAt;} public void setJoinedAt(LocalDateTime v){joinedAt=v;} public LocalDateTime getLastReadAt(){return lastReadAt;} public void setLastReadAt(LocalDateTime v){lastReadAt=v;} public boolean isMuted(){return muted;} public void setMuted(boolean v){muted=v;} public boolean isArchived(){return archived;} public void setArchived(boolean v){archived=v;} public boolean isDeleted(){return deleted;} public void setDeleted(boolean v){deleted=v;}
}
